INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17701, 'Isaiah 59:14', 'Isaiah', 59, 14, '&nbsp;اِنصاف وروستو شوے دے او صداقت لرې ولاړ دے. رښتيا د ښار په چوک کښې تيندک خوړلو سره راپرېوته، او ديانتدارى ورته ورداخلېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17702, 'Isaiah 59:15', 'Isaiah', 59, 15, '&nbsp;رښتيا هيڅوک هم نۀ وائى، او څوک چې غلط کار نه لاس اخلى هغه لوټ کيږى. مالِک خُدائ دا وليدل او هغه په دې نارضا وو چې اِنصاف نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17703, 'Isaiah 59:16', 'Isaiah', 59, 16, '&nbsp;هغۀ وکتل چې هيڅوک هم نۀ وو، هغه حېران شو چې د خلاصى والا څوک هم نۀ وو چې د مظلوم مدد وکړى. خو بيا د هغۀ خپل لاس هغۀ له خلاصون ورکړو، او د هغۀ صداقت د هغۀ مدد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17704, 'Isaiah 59:17', 'Isaiah', 59, 17, '&nbsp;هغۀ صداقت د زغرې په شان واغوستو او د خلاصون ټوپۍ يې په سر کړه. د بدل جامې يې واغوستې او د غېرت څادر يې ځان نه تاو کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17705, 'Isaiah 59:18', 'Isaiah', 59, 18, '&nbsp;هغه به خپلو دشمنانو له د هغوئ د بدو عملونو سزا ورکړى. د هغۀ غضب به د هغۀ په مخالفينو راګزار شى. هغه به د دُنيا تر آخرى سره پورې دوئ له سزا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17706, 'Isaiah 59:19', 'Isaiah', 59, 19, '&nbsp;نو بيا به د نمرپرېواتۀ په طرف خلق د مالِک خُدائ د نوم نه يريږى او نمرخاتۀ په طرف خلق به د هغۀ د نوم جلال بيانوى. ځکه چې هغه به د يو تېز سېلاب په شان په هغوئ راشى لکه چې د مالِک خُدائ باد راروان کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17707, 'Isaiah 59:20', 'Isaiah', 59, 20, '&nbsp;مالِک خُدائ فرمائى چې، ”يو خلاصونکے به صيون ته راځى، د يعقوب هغه اولاد له چې د خپلو ګناهونو نه اوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17708, 'Isaiah 59:21', 'Isaiah', 59, 21, '&nbsp;او ترڅو چې زما خبره ده نو زۀ به هغوئ سره يو لوظ وکړم. زما روح چې په تاسو دے او زما کلام چې ما ستاسو په خولۀ کښې اچولے دے، هغه به هيڅکله ستاسو د خولې نه، ستاسو د اولاد د خولې نه او د هغوئ د اولاد د خولې نه لرې نۀ شى. دا د مالِک خُدائ وينا ده او تر همېشه همېشه پورې به هم داسې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17709, 'Isaiah 60:1', 'Isaiah', 60, 1, '&nbsp;پاڅه، وځلېږه. ځکه چې ستا نُور راغلے دے، او د مالِک خُدائ جلال په تا ځلېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17710, 'Isaiah 60:2', 'Isaiah', 60, 2, '&nbsp;ګورئ، داسې لکه چې په زمکه تيارۀ خوره وى او قومونه تکې تورې تيارۀ لاندې پټ وى، خو په تا باندې به د مالِک خُدائ نُور ځليږى او د هغۀ جلال به ستا دپاسه ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17711, 'Isaiah 60:3', 'Isaiah', 60, 3, '&nbsp;قومونه به ستا نُور له راشى، او بادشاهان به ستا د سحر راختونکې رڼا له راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17712, 'Isaiah 60:4', 'Isaiah', 60, 4, '&nbsp;خپل ځان نه ګېرچاپېره نظر واچوه او وګوره، هغوئ ټول راغونډيږى او تا له راځى. ستا زامن به د لرې لرې نه راشى، او ستا لوڼه به په غېږ کښې راوستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17713, 'Isaiah 60:5', 'Isaiah', 60, 5, '&nbsp;بيا به تۀ دا وګورې او خوشحاله به شې، ستا زړۀ به غټ شى او د خوشحالۍ نه به درزيږى. ځکه چې د لرې مُلکونو خزانې به تا له راوړے شى، او د قومونو دولت به تا له راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17714, 'Isaiah 60:6', 'Isaiah', 60, 6, '&nbsp;د اوښانو غټې قافلې به تا له راشى، د ميديان او عيفه نه به اوښان راشى. هغوئ به د شيبا نه راشى او سرۀ زر او خوشبودارې مصالحې به راوړى او د مالِک خُدائ ثناء صِفت به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17715, 'Isaiah 60:7', 'Isaiah', 60, 7, '&nbsp;د قيدار ټولې ګډې چېلۍ به تا له راوستے شى، او د نبايوت ټول ګډان به ستا خِدمت دپاره حاضر کړے شى. زۀ به په قربان ګاه د هغوئ قربانيانې قبولې کړم او خپلې عبادتخانې له به شان او شوکت ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17716, 'Isaiah 60:8', 'Isaiah', 60, 8, '&nbsp;دا څوک دى چې د وريځې په شان رالوځى، لکه چې ګوګوشتکې جالې ته راروانې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17717, 'Isaiah 60:9', 'Isaiah', 60, 9, '&nbsp;دا د ترسيس سمندرى جهازُونه دى چې تا له راروان دى. ځکه چې دا جزيرې په ما يقين ساتى. دا سمندرى جهازونه ستا اولاد سره د هغوئ د سرو زرو او سپينو زرو د لرې لرې مُلکونو نه راولى، او داسې به ستا د مالِک خُدائ د نوم درناوے وشى، کوم چې د بنى اِسرائيلو مقدس ذات دے، ځکه چې هغۀ تا له شان او شوکت درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17718, 'Isaiah 60:10', 'Isaiah', 60, 10, '&nbsp;د پردى مُلک خلق به ستا دېوالونه بيا جوړ کړى، او د هغوئ بادشاهان به ستا خِدمت کوى. ما په غصه کښې تا له سزا درکړه، خو اوس به زۀ خپل فضل سره په تا رحم وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17719, 'Isaiah 60:11', 'Isaiah', 60, 11, '&nbsp;ستا دروازې به تل کولاو وى، شپه او ورځ به دا نۀ بنديږى، ځکه چې د قومونو مال دولت او د هغوئ ګرفتار شوى بادشاهان به د فتحې په جلوس کښې ښار ته دننه راوستل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17720, 'Isaiah 60:12', 'Isaiah', 60, 12, '&nbsp;خو چې کوم قوم او بادشاهى ستا خِدمت نۀ کوى نو هغوئ به برباد شى، هغوئ به په مکمل طور تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17721, 'Isaiah 60:13', 'Isaiah', 60, 13, '&nbsp;د لبنان شان او شوکت به تا له راشى. د نختر، د صُندل او د سبر ونې به تا له راشى چې زما کور ښائسته کړے شى او داسې به زۀ خپل کور له جلال ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17722, 'Isaiah 60:14', 'Isaiah', 60, 14, '&nbsp;کومو خلقو چې به په تا ظلم زياتے کولو نو د هغوئ اولاد به راځى او د عزت نه به تا ته ټيټيږى. هر چا چې ستا سپکاوے کړے دے نو هغه به ستا پښو ته ټيټيږى. هغوئ به تا ته ”د مالِک خُدائ ښار“ يا ”د بنى اِسرائيلو د مقدس ذات صيون“ نوم اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17723, 'Isaiah 60:15', 'Isaiah', 60, 15, '&nbsp;اول تۀ رد کړے شوے وې او خلقو به تا نه نفرت کولو، او نۀ به څوک په تا کښې تېرېدل. خو اوس به زۀ تا د همېشه دپاره ښائسته کړم او د ټولو نسلونو دپاره به د خوشحالۍ ځائ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17724, 'Isaiah 60:16', 'Isaiah', 60, 16, '&nbsp;طاقتور بادشاهان او زورَور قومونه به ستا هر ضرورت پوره کړى، داسې لکه چې تۀ يو ماشوم يې او د مَلِکې سينه روې. بيا به تا ته پته ولګى چې زۀ مالِک خُدائ ستاسو خلاصونکے، حفاظت کوونکے د بنى اِسرائيلو طاقتور حکمران يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17725, 'Isaiah 60:17', 'Isaiah', 60, 17, '&nbsp;زۀ به ستا زېړ په سرو زرو، اوسپنه په سپينو زرو، لرګى په زېړو او کاڼے په اوسپنه بدل کړم. امن به ستا رهنما او صداقت به ستا حکمران جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17726, 'Isaiah 60:18', 'Isaiah', 60, 18, '&nbsp;ستا په مُلک کښې به نور د ظلم زياتى، تباهۍ او بربادۍ ذکر قدرې نۀ کيږى. تۀ به خپلو دېوالونو ته خلاصون او دروازو ته حمد‌و‌ثناء نوم اخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17727, 'Isaiah 60:19', 'Isaiah', 60, 19, '&nbsp;تا ته به نور د ورځې د نمر ضرورت نۀ وى او د شپې به درته د سپوږمۍ ضرورت نۀ وى، ځکه چې مالِک خُدائ به ستاسو نۀ ختمېدونکے رڼا وى او خُدائ پاک به ستاسو جلال وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17728, 'Isaiah 60:20', 'Isaiah', 60, 20, '&nbsp;ستا نمر به هيڅکله نۀ پرېوځى او نۀ به دې کله سپوږمۍ کوزيږى. ځکه چې مالِک خُدائ به ستا ابدى نُور وى، او ستا د غم ورځې به ختمې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17729, 'Isaiah 60:21', 'Isaiah', 60, 21, '&nbsp;ستا د قوم ټول خلق به صادقان وى، او هغه مُلک به د همېشه دپاره د هغوئ په قبضه کښې وى. ما هغوئ په خپلو لاسونو لکه د ونو په شان کَرلى دى، ترڅو خپله لوئى او جلال ټولو ته ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17730, 'Isaiah 60:22', 'Isaiah', 60, 22, '&nbsp;ستا ټولو نه وړه او کمزورې خاندان به هم د يو طاقتور قوم په شان لويه شى. په مقرر وخت به زۀ داسې وکړم. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17731, 'Isaiah 61:1', 'Isaiah', 61, 1, '&nbsp;د مالِک خُدائ روح په ما نازل دے ځکه چې زۀ هغۀ مسح کړے يم، او دې له يې رالېږلے يم چې غريبانانو ته زېرے ورکړم، مات شوى زړونه روغ کړم، د خلاصون اعلان وکړم او غلامانو ته آزادۍ ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17732, 'Isaiah 61:2', 'Isaiah', 61, 2, '&nbsp;هغۀ زۀ د دې دپاره رالېږلے يم چې د مالِک خُدائ د برکت نه ډک کال اعلان وکړم، او د خُدائ پاک د بدل اخستلو ورځ راغلې ده چې ټولو ماتم کوونکو ته تسلى ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17733, 'Isaiah 61:3', 'Isaiah', 61, 3, '&nbsp;څوک چې په صيون کښې ماتم کوى نو هغوئ له به د ايرو په ځائ ښائسته تاج ورکړم، او د غم په ځائ به خوشحالى ورکړم، او د پرېشانۍ په ځائ به حمد‌و‌ثناء ورکړم. هغوئ به په خپل صداقت کښې د څېړۍ د داسې ونو په شان وى چې مالِک خُدائ په خپله د خپل جلال دپاره کَرلى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17734, 'Isaiah 61:4', 'Isaiah', 61, 4, '&nbsp;هغوئ به پخوانى کنډرات بيا آباد کړى او د هغه ځايونو مرمت به وکړى کوم چې ډېره موده مخکښې تباه شوى وُو. هغوئ به هغه تباه شوى ښارونه بيا قائم کړى کوم چې تر ډېرو نسلونو پورې غېر آباد وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17735, 'Isaiah 61:5', 'Isaiah', 61, 5, '&nbsp;د نورو مُلکونو خلق به ستاسو خِدمت کوى. هغوئ به ستاسو د رَمو خيال ساتى، ستاسو پټو کښې به يوه کوى او ستاسو د انګورو د باغونو خيال به ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17736, 'Isaiah 61:6', 'Isaiah', 61, 6, '&nbsp;په هغه وخت به تاسو د مالِک خُدائ اِمامان يادېږئ، او خلق به تاسو ته د خُدائ پاک خادِمان وائى. تاسو به د نورو قومونو د مال دولت نه خوند واخلئ او د هغوئ نه چې کوم مال حال تاسو ته ملاويږى په هغې به لافې وهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17737, 'Isaiah 61:7', 'Isaiah', 61, 7, '&nbsp;د بې‌عزتۍ او سپکاوى په ځائ به تاسو ته يو په دوه عزت درکړے شى. په خپل مُلک کښې به تاسو د مال دولت يو په دوه حِصه دار يئ، او ستاسو خوشحالى به د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17738, 'Isaiah 61:8', 'Isaiah', 61, 8, '&nbsp;مالِک خُدائ فرمائى، ”زۀ د اِنصاف سره مينه کوم او زۀ د غلا او بدۍ نه نفرت کوم. زۀ به وفادارۍ سره خپلو خلقو له د هغوئ اجر ورکړم او د هغوئ سره به د همېشه دپاره يو لوظ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17739, 'Isaiah 61:9', 'Isaiah', 61, 9, '&nbsp;د هغوئ نسل به په قومونو کښې او د هغوئ اولاد به په اُمتونو کښې مشهور شى، هر څوک چې هغوئ وګورى نو پته به ورته لګى چې دا هغه خلق دى چا له چې مالِک خُدائ برکت ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17740, 'Isaiah 61:10', 'Isaiah', 61, 10, '&nbsp;زۀ په مالِک خُدائ کښې ډېر خوشحاله يم. زما ځان د خُدائ پاک په تعريف کښې د خوشحالۍ سندرې وائى. ځکه لکه څنګه چې د وادۀ زلمے د وادۀ په جوړه کښې او ناوې په کالو ځان سنګار کړے وى داسې مالِک خُدائ زۀ د خلاصون په لباس او د صداقت په څادر کښې رانغښتے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17741, 'Isaiah 61:11', 'Isaiah', 61, 11, '&nbsp;لکه څنګه چې زمکه شينکے راټوکوى او باغ خپل تخم زرغونوى، نو داسې به خُدائ تعالىٰ خلق صداقت ته جوړ کړى او دوئ به د ټولو قومونو په مخکښې د هغۀ ثناء او صِفت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17742, 'Isaiah 62:1', 'Isaiah', 62, 1, '&nbsp;د صيون د خاطره به زۀ غلے نۀ کښېنم، د يروشلم د خاطره به زۀ تر هغې پورې آرام نۀ کوم چې د هغې صداقت د سحر د رڼا په شان ونۀ ځليږى او د هغې خلاصون د مشعل په شان ونۀ ځليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17743, 'Isaiah 62:2', 'Isaiah', 62, 2, '&nbsp;قومونه به ستا صداقت ووينى، او ټول بادشاهان به ستا شان او شوکت وګورى. او تا ته به يو نوے نوم درکړے شى، يو داسې نوم چې مالِک خُدائ به په خپله خولۀ درباندې اېښے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17744, 'Isaiah 62:3', 'Isaiah', 62, 3, '&nbsp;نو تۀ به د مالِک خُدائ په لاس کښې د شاندار تاج په شان يې او د خپل خُدائ پاک په لاس کښې به د شاهى پټکى په شان يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17745, 'Isaiah 62:4', 'Isaiah', 62, 4, '&nbsp;تا ته به بيا هيڅکله ”پرېښودلے شوے ښار“ نوم نۀ شى اخستلے، او نۀ به ستا زمکې ته ”خوشے مُلک“ نوم اخستلے شى. ستا نوے نوم به ”د خُدائ پاک د خوشحالۍ ښار“ او ”د خُدائ پاک ناوې“ وى، ځکه چې مالِک خُدائ ستا نه خوشحال دے او ستا نه به خپله ناوې جوړه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17746, 'Isaiah 62:5', 'Isaiah', 62, 5, '&nbsp;لکه څنګه چې يو زلمے يوې پېغلې سره وادۀ کوى، نو داسې به ستا زامن تا سره لوظ وکړى. لکه څنګه چې د وادۀ زلمے د خپلې ناوې سره خوشحاله وى، نو داسې خُدائ پاک به ستا نه خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17747, 'Isaiah 62:6', 'Isaiah', 62, 6, '&nbsp;اے يروشلمه، ستا په دېوالونو ما څوکيداران ودرولى دى، هغوئ به شپه او ورځ مسلسل دُعا کوى. تاسو چې څوک مالِک خُدائ ته دُعا کوئ هيڅ آرام مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17748, 'Isaiah 62:7', 'Isaiah', 62, 7, '&nbsp;او مۀ مالِک خُدائ آرام ته پرېږدئ ترڅو چې هغۀ يروشلم قائم کړى نۀ وى او د دُنيا دپاره يې د فخر باعث جوړ کړى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17749, 'Isaiah 62:8', 'Isaiah', 62, 8, '&nbsp;مالِک خُدائ په خپل ښى لاس او زورَور مټ باندې قسم خوړلے دے او لوظ يې کړے دے چې، ”زۀ به بيا ستا غله ستا په دشمنانو نۀ خوروم، او نۀ به محنت سره جوړ شوى ستا مے د پردى مُلک خلقو باندې څښوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17750, 'Isaiah 62:9', 'Isaiah', 62, 9, '&nbsp;خو چا چې دا غله رېبلې وى نو هغوئ به دا خورى او د مالِک خُدائ ثناء صِفت به کوى. او چا چې دا انګور راټول کړى وى نو هغوئ به په خپله د دې شراب د مالِک خُدائ د کور په دربار کښې وڅښى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17751, 'Isaiah 62:10', 'Isaiah', 62, 10, '&nbsp;بهر لاړ شئ، د ښار دروازو نه بهر لاړ شئ. او چې کوم خلق واپس راځى نو د هغوئ دپاره يو سړک جوړ کړئ. يو لوئ سړک تيار کړئ، د دې نه کاڼى لرې کړئ. يوه جنډا ولګوئ چې قومونو ته پته لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17752, 'Isaiah 62:11', 'Isaiah', 62, 11, '&nbsp;ګورئ، مالِک خُدائ ټولې دُنيا ته دا اعلان کوى، ”د صيون لور ته ووايئ چې ګورئ، ستاسو خلاصون راتلونکے دے. ګورئ، د هغۀ اجر د هغۀ سره دے، او د هغۀ انعام د هغۀ نه مخکښې مخکښې روان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17753, 'Isaiah 62:12', 'Isaiah', 62, 12, '&nbsp;هغوئ ته به ”مقدس خلق“ او ”د مالِک خُدائ بچ کړے شوى خلق“ نوم اخستلے شى. او يروشلم ته به ”غوره کړے شوے ښار،“ ”هغه ښار چې پرېښودے شوے نۀ وى“ نوم اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17754, 'Isaiah 63:1', 'Isaiah', 63, 1, '&nbsp;دا څوک دے چې د ادوم نه راروان دے، سرې جامې يې اغوستې دى او د بُصره ښار نه راروان دے؟ دا څوک دے چا چې د رُعب شاهى لباس اغوستے دے او قوت سره روان دے؟ ”هم زۀ يم، چې د صداقت اعلان کوم، او د بچ کولو طاقت لرم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17755, 'Isaiah 63:2', 'Isaiah', 63, 2, '&nbsp;ستا جامې ولې دومره سرې دى؟ داسې لکه چې ستا جامې د انګورو نچوړولو سره سرې شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17756, 'Isaiah 63:3', 'Isaiah', 63, 3, '&nbsp;”ما يواځې انګور نچوړ کړى دى، په قومونو کښې هيڅ څوک هم ما سره نۀ وو. ما په غصه کښې هغوئ نچوړ کړى دى او د قهر نه پرې ګرځېدلے يم. د هغوئ د وينې دارې زما په کپړو پرېوتې دى او زما جامې په وينو سرې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17757, 'Isaiah 63:4', 'Isaiah', 63, 4, '&nbsp;ځکه چې هغه وخت راغلے دے چې د خپلو خلقو دپاره بدل واخلم. او هغه کال راغلے دے چې هغوئ په بيعه واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17758, 'Isaiah 63:5', 'Isaiah', 63, 5, '&nbsp;زۀ حېران شوم چې هيڅوک نۀ وو چې خلاصے يې کړے وے او د مظلومانو مدد يې کړے وے. نو زۀ پخپله وروړاندې شوم چې هغوئ د خپل مضبوط لاس سره بچ کړم. او زما غصې زما مدد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17759, 'Isaiah 63:6', 'Isaiah', 63, 6, '&nbsp;ما په خپله غصه کښې قومونه چخڼى او نشه کړل او د هغوئ وينه مې په زمکه توئ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17760, 'Isaiah 63:7', 'Isaiah', 63, 7, '&nbsp;زۀ به د مالِک خُدائ د نۀ ختمېدونکې مينې بيان وکړم، هر څۀ چې هغۀ زمونږ دپاره کړى دى نو د هغې دپاره به زۀ د هغۀ ثناء صِفت کوم. هغۀ چې بنى اِسرائيلو سره بې‌شمېره ښېګړې کړې دى په هغې به خوشحالى کوم، کومې چې هغۀ د خپل رحم او مينې په مطابق کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17761, 'Isaiah 63:8', 'Isaiah', 63, 8, '&nbsp;هغۀ وفرمائيل، ”دوئ زما خپل خلق دى، يقيناً چې هغوئ به ما سره دوکه نۀ کوى.“ او هغه د هغوئ خلاصونکے جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17762, 'Isaiah 63:9', 'Isaiah', 63, 9, '&nbsp;هغه د هغوئ په ټولو تکليفونو کښې شريک شو. او هغوئ هغه فرښتې بچ کړل کومه چې د خُدائ پاک د حضور نه ورغلې وه. د خپلې مينې او زړۀ سواندى له وجې يې هغوئ په بيعه واخستل، او ټوله پخوانۍ زمانه کښې يې هغوئ اوچت کړى وُو او ګرځول يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17763, 'Isaiah 63:10', 'Isaiah', 63, 10, '&nbsp;خو هغوئ د هغۀ خِلاف سرکشى وکړه او د هغۀ مقدس روح يې خفه کړو. نو مالِک خُدائ د هغوئ دشمن شو او د هغوئ خِلاف يې جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17764, 'Isaiah 63:11', 'Isaiah', 63, 11, '&nbsp;بيا هغوئ ته هغه تېره زمانه راياده شوه کله چې موسىٰ د خپلو خلقو د مِصر نه راوتو کښې رهنمائى کوله. هغوئ چغه کړه، ”هغه چرته دے چا چې بنى اِسرائيل د سمندر نه پورې ويستل، چې موسىٰ د هغوئ شپون وو؟ هغه چرته دے چا چې خپل مقدس روح راولېږلو چې د هغۀ د خلقو په مينځ کښې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17765, 'Isaiah 63:12', 'Isaiah', 63, 12, '&nbsp;هغه چرته دے چا چې خپل طاقت څرګند کړو کله چې موسىٰ خپل لاس اوچت کړو، هغه چرته دے چا چې د هغوئ په وړاندې سمندر تقسيم کړو او خپل ځان يې د همېشه دپاره مشهور کړو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17766, 'Isaiah 63:13', 'Isaiah', 63, 13, '&nbsp;هغه چرته دے چا چې د سمندر بېخ کښې د دوئ په تېرېدو کښې رهنمائى وکړه؟“ هغوئ لکه د ښو آسونو په شان وُو چې په صحرا کښې تېز روان وُو او هيڅ تيندکونه يې نۀ خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17767, 'Isaiah 63:14', 'Isaiah', 63, 14, '&nbsp;لکه څنګه چې څاروى د آرام وادۍ ته کوزيږى، داسې د مالِک خُدائ روح هغوئ له آرام ورکړو. مالِک خُدائ خپل خلق بوتلل او د هغۀ د نوم درناوے وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17768, 'Isaiah 63:15', 'Isaiah', 63, 15, '&nbsp;اے مالِکه خُدايه، د آسمان نه په مونږ نظر وکړه، چرته چې تۀ د پاکوالى او جلال سره اوسېږې. ستا غېرت او ستا طاقت چرته دے؟ مونږ ستا د رحم او همدردۍ نه محروم پاتې شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17769, 'Isaiah 63:16', 'Isaiah', 63, 16, '&nbsp;هم تۀ زمونږه پلار يې. اګر کۀ اِبراهيم او يعقوب مونږ خپل نۀ ګڼى، خو بيا هم مالِکه خُدايه، هم تۀ زمونږه پلار يې، د پخوا نه تۀ زمونږ بچ کوونکے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17770, 'Isaiah 63:17', 'Isaiah', 63, 17, '&nbsp;اے مالِکه خُدايه، تا ولې مونږ دې ته مجبور کړو چې ستا لارې نه واوړُو؟ او زمونږ زړونه دې ولې دومره سخت کړل چې ستا نه نۀ يريږو؟ د خپلو خِدمت کوونکو د خاطره راوګرځه، د هغه قبيلو د خاطره چې ستا ميراث دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17771, 'Isaiah 63:18', 'Isaiah', 63, 18, '&nbsp;ستا مقدس ځائ د لږ وخت دپاره ستا مقدسو خلقو سره وو، خو اوس زمونږ دشمنانو هغه تباه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17772, 'Isaiah 63:19', 'Isaiah', 63, 19, '&nbsp;کله کله خو داسې ښکارى لکه چې مونږ هډو ستا خلق نۀ وُو او نۀ کله ستا د خلقو د نوم پورې تړلې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17773, 'Isaiah 64:1', 'Isaiah', 64, 1, '&nbsp;اے، چې تۀ آسمان وشلوې او راکوز شې، نو غرونه به تا وګورى او ستا په وړاندې به په ريږدېدو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17774, 'Isaiah 64:2', 'Isaiah', 64, 2, '&nbsp;لکه څنګه چې اور لرګى سيزى او اوبۀ خوټکوى، نو ستا راتګ به قومونه ولړزوى. بيا به ستا دشمنانو ته ستا د مشهورتيا پته ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17775, 'Isaiah 64:3', 'Isaiah', 64, 3, '&nbsp;پخوا کله چې تا يروونکى کارونه وکړل چې مونږ يې هيڅ توقع نۀ کوله، نو تۀ داسې راکوز شوې چې غرونه ستا په وړاندې په لړزان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17776, 'Isaiah 64:4', 'Isaiah', 64, 4, '&nbsp;د پخوا نه نۀ ستا په شان خُدائ پاک چا ليدلے دے او نۀ يې اورېدلې دى، صرف تۀ هغه خُدائ يې چې د هغوئ مدد کوې څوک چې ستا په انتظار کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17777, 'Isaiah 64:5', 'Isaiah', 64, 5, '&nbsp;تۀ هغه خلقو ته هرکلے وائې څوک چې په خوشحالۍ سره د صداقت کارونه کوى او ستا په لار ځى. ګوره، تۀ مونږ ته غصه وې، خو مونږ ګناه نۀ پرېښودله، چې د ډېرې زمانې نه مونږ په ګناه کښې بوخت يُو، نو څنګه به بچ شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17778, 'Isaiah 64:6', 'Isaiah', 64, 6, '&nbsp;مونږ ټول د هغه سړى په شان يُو څوک چې ناپاک وى، او زمونږ ټول ښۀ عملونه د پليتې کپړې په شان دى. مونږ د خزان د پاڼو په شان مړاوى شُو او راپرېوځو، او زمونږ ګناهونه مونږ لکه د هوا په شان جارُو کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17779, 'Isaiah 64:7', 'Isaiah', 64, 7, '&nbsp;هيڅ څوک هم ستا نوم نۀ اخلى او نۀ تا ته د رحم سوال کوى. تا زمونږ نه مخ اړولے دے او مونږ دې زمونږ د ګناه په حواله کړې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17780, 'Isaiah 64:8', 'Isaiah', 64, 8, '&nbsp;خو اے مالِکه خُدايه، تۀ زمونږ پلار يې. مونږ د خټې په شان يُو او تۀ د کُلال په شان يې. تا مونږ جوړ کړى يُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17781, 'Isaiah 64:9', 'Isaiah', 64, 9, '&nbsp;مونږ ته سخت مۀ غصه کېږه او زمونږ ګناه د همېشه دپاره ياده مۀ ساته. مونږ ته وګوره، مونږ تا ته مِنت کوُو، او ګوره مونږ ټول هم ستا خلق يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17782, 'Isaiah 64:10', 'Isaiah', 64, 10, '&nbsp;ستا مقدس ښارونه تباه شوى دى، د صيون نه بيابان جوړ شوے دے، او د يروشلم نه کنډر جوړ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17783, 'Isaiah 64:11', 'Isaiah', 64, 11, '&nbsp;او ستا هغه ښائسته او مقدس کور، چرته چې زمونږ پلار نيکۀ ستا ثناء صِفت کولو، اور سيزلے دے. او زمونږ د خوښې ټول ځايونو نه کنډر جوړ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17784, 'Isaiah 64:12', 'Isaiah', 64, 12, '&nbsp;اے مالِکه خُدايه، د دې هر څۀ باوجود به تۀ زمونږ مدد نه اِنکار کوې څۀ؟ خاموش به يې او بې‌انتها سزا به راکوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17785, 'Isaiah 65:1', 'Isaiah', 65, 1, '&nbsp;مالِک خُدائ فرمائى، ”ما خپل ځان هغوئ ته څرګند کړو چا چې زما تپوس نۀ کولو، او په هغوئ مې ځان پېدا کړو چا چې زما لټون نۀ کولو. ما وئيل چې، زۀ حاضر يم، زۀ حاضر يم. خو بيا هم دې قوم زما نوم نۀ اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17786, 'Isaiah 65:2', 'Isaiah', 65, 2, '&nbsp;ما ټوله ورځ سرکشه خلقو ته لاسونه کولاو نيولى وُو. خو هغوئ په خپلو غلطو لارو ځى او ګډو وډو خيالونو پسې ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17787, 'Isaiah 65:3', 'Isaiah', 65, 3, '&nbsp;هغوئ مسلسل زما په وړاندې زما بې‌ادبى کوى. هغوئ په مقدسو باغونو کښې قربانيانې پېش کوى او د غېرو قومونو په قربان‌ګاه باندې خوشبويۍ سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17788, 'Isaiah 65:4', 'Isaiah', 65, 4, '&nbsp;هغوئ په قبرستان کښې کښېنى او په پټو ځايونو کښې شپې تېروى. هغوئ د خنزير غوښه خورى، او د حرام خوراک ښوروا د هغوئ په لوښو کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17789, 'Isaiah 65:5', 'Isaiah', 65, 5, '&nbsp;او بيا دوئ يو بل ته وائى، ”ما ته مۀ رانزدې کېږه ګنې ما به پليت کړې. زۀ ستا نه زيات مقدس يم.“ داسې خلق زما په سپېږمو کښې د بدبوئ په شان دى، د داسې خراب بوئ په شان چې هيڅکله نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17790, 'Isaiah 65:6', 'Isaiah', 65, 6, '&nbsp;ګورئ، دا زما په وړاندې ليکلے شوى دى، زۀ به غلے نۀ پاتې کېږم او هغوئ له به پوره پوره سزا ورکوم. آو، بې‌شکه زۀ به هغوئ نه بدله اخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17791, 'Isaiah 65:7', 'Isaiah', 65, 7, '&nbsp;مالِک خُدائ فرمائى، ”هغوئ ته به نۀ صرف د خپلو ګناهونو بلکې د پلار نيکۀ د ګناهونو سزا به هم ورته ملاويږى. ځکه چې هغوئ په غرونو کښې خوشبويانې سوزولې دى او زما بې‌ادبې يې کړې ده. نو ځکه به هغوئ له پوره پوره سزا ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17792, 'Isaiah 65:8', 'Isaiah', 65, 8, '&nbsp;مالِک خُدائ فرمائى، ”ترڅو پورې چې په انګورو کښې لږ رس پاتې وى نو خلق وائى، چې دا مۀ ضائع کوئ، ځکه چې په دې کښې څۀ نه څۀ شته چې باعثِ برکت دى. زۀ به بنى اِسرائيلو سره هم داسې کوم. د خپلو خادِمانو د خاطره به زۀ ټول نۀ تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17793, 'Isaiah 65:9', 'Isaiah', 65, 9, '&nbsp;زۀ به يعقوب او يهوداه له داسې اولاد ورکړم چې زما غرونه به قبضه کړى. زما غوره کړے شوى به د دې وارثان شى او زما خِدمت کوونکى به هلته اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17794, 'Isaiah 65:10', 'Isaiah', 65, 10, '&nbsp;د شارون په مېدان کښې به ګډې چېلۍ څرى او د مصيبت په وادۍ کښې به څاروى آرام کوى. دا به زما د هغه خلقو دپاره وى چې څوک زما لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17795, 'Isaiah 65:11', 'Isaiah', 65, 11, '&nbsp;خو تاسو چا چې مالِک خُدائ ته شا کړه او زما مقدس غر مو هېر کړو، چا چې د قِسمت معبود ته دسترخوان ويړ کړو او د بخت معبود ته مو د ميو جامونه ډک کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17796, 'Isaiah 65:12', 'Isaiah', 65, 12, '&nbsp;اوس به زۀ تُوره ستاسو په قِسمت کړم. تاسو ټول به د حلالونکى په وړاندې ټيټ شئ، ځکه چې کله ما آواز درکړو، نو تاسو جواب رانۀ کړو، او چې کله مې درسره کلام کولو، نو تاسو نۀ اورېدو. او زما د سترګو په وړاندې تاسو قصداً ګناه کوله او هغه څۀ به مو کول د څۀ چې تاسو ته پته ده چې زۀ ترې نفرت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17797, 'Isaiah 65:13', 'Isaiah', 65, 13, '&nbsp;نو ځکه مالِک خُدائ تعالىٰ فرمائى، ”زما خادِمان به خوراک کوى خو تاسو به اوږى يئ. زما خادِمان به څښل کوى خو تاسو به تږى يئ. زما خادِمان به خوشحالى کوى خو تاسو به غمژن او په شرم پټ يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17798, 'Isaiah 65:14', 'Isaiah', 65, 14, '&nbsp;زما خادِمان به د خوشحالۍ سندرې وائى، خو تاسو به په مايوسۍ او غمژن زړۀ سره ژړا کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17799, 'Isaiah 65:15', 'Isaiah', 65, 15, '&nbsp;زما د غوره کړے شوو خلقو په مينځ کښې به ستاسو نوم لعنتى وى، ځکه چې مالِک خُدائ به تاسو تباه کړى. او خپلو حقيقى خادِمانو له به يو بل نوم ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17800, 'Isaiah 65:16', 'Isaiah', 65, 16, '&nbsp;نو چې په مُلک کښې هر څوک هم د برکت دُعا غواړى نو هغه به د رښتياو خُدائ پاک په نوم برکت غواړى. هر څوک هم چې قسم کوى نو هغه به د رښتياو خُدائ پاک په نوم قسم خورى. ځکه چې د تېرې زمانې تکليفونه به هېر کړے شى. او زما د سترګو نه به پناه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');